1	import {
2	  $,
3	  component$,
4	  useSignal,
5	  useStore,
6	  useVisibleTask$,
7	} from "@qwik.dev/core";
8	import { Link, type DocumentHead } from "@qwik.dev/router";
9	import { api } from "../../../convex/_generated/api";
10	import {
11	  combinedDataIsPartial,
12	  combineDeskUsage,
13	  type ServerBreakdownRow,
14	  type ServerDailyUsage,
15	  type ServerUsageMetrics,
16	  type ServerWritingActivity,
17	} from "../../components/desk/desk-data";
18	import {
19	  DeskSummary,
20	  type SynchronizedCoverage,
21	} from "../../components/desk/desk-summary";
22	import { RecentWork } from "../../components/desk/recent-work";
23	import { UsageCost } from "../../components/desk/usage-cost";
24	import { WriterPatterns } from "../../components/desk/writer-patterns";
25	import { WritingActivity } from "../../components/desk/writing-activity";
26	import {
27	  hasAuthenticatedConvexIdentity,
28	  useAuth,
29	} from "../../utils/auth-context";
30	import { getNotOrganicHostedUsage } from "../../utils/notorganic-provider";
31	import type { HostedUsageSummary } from "../../utils/hosted-usage";
32	import type { HostedCostState } from "../../components/desk/hosted-cost";
33	import { computeCreditRunway } from "../../utils/credit-runway";
34	import {
35	  FORECAST_PREVIEW_EVENT,
36	  type CreditForecast,
37	} from "../../utils/writing-forecasts";
38	import { accountDisplayName } from "../../utils/account-display";
39	import { useConvexClient } from "../../utils/convex-context";
40	import { loadFolioContentFromIdb, loadFoliosFromIdb } from "../../utils/idb";
41	import {
42	  captureProductEvent,
43	  countDraftWords,
44	} from "../../utils/product-analytics";
45	import {
46	  createUsageRange,
47	  type UsageEvent,
48	  type UsageRange,
49	  type UsageRangePreset,
50	} from "../../utils/usage-domain";
51	import { usageLedger } from "../../utils/usage-ledger";
52	import {
53	  buildUsageSummary,
54	  type FolioUsageMetadata,
55	  type UsageSummary,
56	} from "../../utils/usage-summary";
57	
58	const RANGE_LABELS: Record<UsageRangePreset, string> = {
59	  "7d": "Last 7 UTC days",
60	  "30d": "Last 30 UTC days",
61	  "90d": "Last 90 UTC days",
62	  all: "All recorded usage",
63	};
64	const MAX_LOCAL_PAGES = 20;
65	const MAX_REMOTE_PAGES = 10;
66	
67	interface DeskStore {
68	  summary: UsageSummary;
69	  titles: Record<string, string>;
70	  folioCount: number;
71	  writingDays: number;
72	  loaded: boolean;
73	  detailsTruncated: boolean;
74	  combinedPartial: boolean;
75	  remoteState: "idle" | "loading" | "ready" | "offline" | "error";
76	  synchronized?: SynchronizedCoverage;
77	}
78	
79	interface EventPage {
80	  events: UsageEvent[];
81	  truncated: boolean;
82	}
83	
84	async function listLocalEvents(range: UsageRange): Promise<EventPage> {
85	  const events: UsageEvent[] = [];
86	  let cursor: string | undefined;
87	  let pages = 0;
88	  do {
89	    const page = await usageLedger.listUsageEvents({
90	      from: range.from,
91	      to: range.to,
92	      cursor,
93	    });
94	    events.push(...page.events);
95	    cursor = page.cursor;
96	    pages += 1;
97	  } while (cursor && pages < MAX_LOCAL_PAGES);
98	  return { events, truncated: Boolean(cursor) };
99	}
100	
101	async function listPendingEvents(
102	  accountId: string,
103	  range: UsageRange,
104	): Promise<EventPage> {
105	  const events: UsageEvent[] = [];
106	  let cursor: string | undefined;
107	  let pages = 0;
108	  do {
109	    const page = await usageLedger.listPendingUsageEvents({
110	      accountId,
111	      cursor,
112	      limit: 100,
113	    });
114	    events.push(
115	      ...page.events.filter(
116	        (event) =>
117	          event.occurredAt < range.to &&
118	          (range.from === null || event.occurredAt >= range.from),
119	      ),
120	    );
121	    cursor = page.cursor;
122	    pages += 1;
123	  } while (cursor && pages < MAX_LOCAL_PAGES);
124	  return { events, truncated: Boolean(cursor) };
125	}
126	
127	async function folioMetadata() {
128	  const folios = await loadFoliosFromIdb();
129	  const metadata: FolioUsageMetadata[] = await Promise.all(
130	    folios.map(async (folio) => ({
131	      folioId: folio.id,
132	      currentWords: countDraftWords(await loadFolioContentFromIdb(folio.id)),
133	      updatedAt: folio.updatedAt,
134	    })),
135	  );
136	  return { folios, metadata };
137	}
138	
139	export default component$(() => {
140	  const now = Date.now();
141	  const auth = useAuth();
142	  const clientSignal = useConvexClient();
143	  const preset = useSignal<UsageRangePreset>("30d");
144	  const hostedRevision = useSignal(0);
145	  const hostedSummary = useSignal<HostedUsageSummary>();
146	  const hostedState = useSignal<HostedCostState>("loading");
147	  const hostedRunway = useSignal<CreditForecast | null>(null);
148	  const deskViewCaptured = useSignal(false);
149	  const initialRange = createUsageRange("30d", now);
150	  const store = useStore<DeskStore>({
151	    summary: buildUsageSummary({
152	      events: [],
153	      activities: [],
154	      range: initialRange,
155	      now,
156	    }),
157	    titles: {},
158	    folioCount: 0,
159	    writingDays: 0,
160	    loaded: false,
161	    detailsTruncated: false,
162	    combinedPartial: false,
163	    remoteState: "idle",
164	  });
165	
166	  // Billing evidence is independent of browser-ledger synchronization.
167	  // eslint-disable-next-line qwik/no-use-visible-task
168	  useVisibleTask$(async ({ track, cleanup }) => {
169	    const client = track(() => clientSignal.value);
170	    const authState = track(() => auth.value);
171	    const selectedPreset = track(() => preset.value);
172	    track(() => hostedRevision.value);
173	    let cancelled = false;
174	    cleanup(() => {
175	      cancelled = true;
176	    });
177	    hostedSummary.value = undefined;
178	    if (!authState.user && !authState.loading) {
179	      hostedState.value = "signed-out";
180	      return;
181	    }
182	    hostedState.value = "loading";
183	    if (!client || !hasAuthenticatedConvexIdentity(authState)) return;
184	    try {
185	      const summary = await getNotOrganicHostedUsage(
186	        client,
187	        createUsageRange(selectedPreset, Date.now()),
188	      );
189	      if (!cancelled) {
190	        hostedSummary.value = summary;
191	        hostedState.value = "ready";
192	      }
193	    } catch {
194	      if (!cancelled) hostedState.value = "error";
195	    }
196	  });
197	
198	  // The runway is always this calendar month, whatever range is selected.
199	  // eslint-disable-next-line qwik/no-use-visible-task
200	  useVisibleTask$(async ({ track, cleanup }) => {
201	    const client = track(() => clientSignal.value);
202	    const authState = track(() => auth.value);
203	    track(() => hostedRevision.value);
204	    let cancelled = false;
205	    cleanup(() => {
206	      cancelled = true;
207	    });
208	    const accountId = authState.user?.analyticsId;
209	    hostedRunway.value = null;
210	    if (!client || !accountId || !hasAuthenticatedConvexIdentity(authState))
211	      return;
212	    try {
213	      const runway = await computeCreditRunway(client, accountId, Date.now(), {
214	        isCurrent: () => !cancelled,
215	      });
216	      if (!cancelled) hostedRunway.value = runway;
217	    } catch {
218	      if (!cancelled) hostedRunway.value = null;
219	    }
220	  });
221	
222	  // Development only: a stubbed runway and wallet summary for browser checks.
223	  // eslint-disable-next-line qwik/no-use-visible-task
224	  useVisibleTask$(({ cleanup }) => {
225	    if (!import.meta.env.DEV) return;
226	    const onPreview = (event: Event) => {
227	      const detail = (
228	        event as CustomEvent<{
229	          credit?: CreditForecast;
230	          hosted?: HostedUsageSummary;
231	        }>
232	      ).detail;
233	      if (detail?.hosted) {
234	        hostedSummary.value = detail.hosted;
235	        hostedState.value = "ready";
236	      }
237	      hostedRunway.value = detail?.credit ?? null;
238	    };
239	    window.addEventListener(FORECAST_PREVIEW_EVENT, onPreview);
240	    cleanup(() =>
241	      window.removeEventListener(FORECAST_PREVIEW_EVENT, onPreview),
242	    );
243	  });
244	
245	  // Validate the URL before the ledger tasks react to a non-default range.
246	  // eslint-disable-next-line qwik/no-use-visible-task
247	  useVisibleTask$(() => {
248	    const value = new URLSearchParams(location.search).get("range");
249	    if (value === "7d" || value === "30d" || value === "90d" || value === "all")
250	      preset.value = value;
251	    else if (value !== null)
252	      history.replaceState(history.state, "", "/desk/?range=30d");
253	  });
254	
255	  // Local-first paint: this never waits for auth, network, or Convex.
256	  // eslint-disable-next-line qwik/no-use-visible-task
257	  useVisibleTask$(async ({ cleanup, track }) => {
258	    const selectedPreset = track(() => preset.value);
259	    let cancelled = false;
260	    cleanup(() => {
261	      cancelled = true;
262	    });
263	    store.loaded = false;
264	    const loadedAt = Date.now();
265	    const range = createUsageRange(selectedPreset, loadedAt);
266	    const [{ events, truncated }, localFolios, activities] = await Promise.all([
267	      listLocalEvents(range),
268	      folioMetadata(),
269	      usageLedger.listWritingActivity({
270	        from: range.from ?? 0,
271	        to: range.to,
272	        limit: 2_000,
273	      }),
274	    ]);
275	    if (cancelled) return;
276	    store.titles = Object.fromEntries(
277	      localFolios.folios.map((folio) => [folio.id, folio.name]),
278	    );
279	    store.folioCount = localFolios.folios.length;
280	    store.detailsTruncated = truncated || activities.length === 2_000;
281	    store.combinedPartial = false;
282	    const summary = buildUsageSummary({
283	      events,
284	      activities,
285	      folios: localFolios.metadata,
286	      range,
287	      now: loadedAt,
288	    });
289	    store.summary = summary;
290	    store.writingDays = summary.writingHeatmap.filter(
291	      (day) => day.count > 0,
292	    ).length;
293	    store.loaded = true;
294	  });
295	
296	  // Signed-in rebase: server aggregates are authoritative; only pending local
297	  // events are added so already-synchronized browser rows cannot double count.
298	  // eslint-disable-next-line qwik/no-use-visible-task
299	  useVisibleTask$(async ({ cleanup, track }) => {
300	    const client = track(() => clientSignal.value);
301	    const provider = track(() => auth.value.provider);
302	    const user = track(() => auth.value.user);
303	    const loading = track(() => auth.value.loading);
304	    const selectedPreset = track(() => preset.value);
305	    const localLoaded = track(() => store.loaded);
306	    let cancelled = false;
307	    cleanup(() => {
308	      cancelled = true;
309	    });
310	    if (loading || provider !== "convex" || !user || !client || !localLoaded) {
311	      store.remoteState =
312	        typeof navigator !== "undefined" && !navigator.onLine
313	          ? "offline"
314	          : "idle";
315	      store.synchronized = undefined;
316	      return;
317	    }
318	    const accountId = user.analyticsId;
319	    if (!accountId || !navigator.onLine) {
320	      store.remoteState = navigator.onLine ? "error" : "offline";
321	      return;
322	    }
323	    store.remoteState = "loading";
324	    const queriedAt = Date.now();
325	    const requested = createUsageRange(selectedPreset, queriedAt);
326	    const recent =
327	      selectedPreset === "all" ? createUsageRange("90d", queriedAt) : requested;
328	    const loadBreakdown = async (
329	      dimension: "feature" | "provider_model" | "folio",
330	    ) => {
331	      const rows: ServerBreakdownRow[] = [];
332	      let cursor: string | null = null;
333	      let isDone = false;
334	      let pages = 0;
335	      while (!isDone && pages < MAX_REMOTE_PAGES) {
336	        const result = (await client.query(api.usage.getMyBreakdown, {
337	          from: requested.from,
338	          to: requested.to,
339	          now: queriedAt,
340	          dimension,
341	          paginationOpts: { numItems: 100, cursor },
342	        })) as unknown as {
343	          page: ServerBreakdownRow[];
344	          isDone: boolean;
345	          continueCursor: string;
346	        };
347	        rows.push(...result.page);
348	        cursor = result.continueCursor;
349	        isDone = result.isDone;
350	        pages += 1;
351	      }
352	      return { rows, truncated: !isDone };
353	    };
354	    try {
355	      const [
356	        coverage,
357	        remoteOverall,
358	        remoteDaily,
359	        remoteWriting,
360	        feature,
361	        providerModel,
362	        folio,
363	        recentPage,
364	        pending,
365	        localActivities,
366	        localFolios,
367	      ] = await Promise.all([
368	        client.query(api.usage.getMyCoverage, {}),
369	        client.query(api.usage.getMySummary, {
370	          from: requested.from,
371	          to: requested.to,
372	          now: queriedAt,
373	        }),
374	        client.query(api.usage.getMyDaily, {
375	          from: recent.from!,
376	          to: recent.to,
377	        }),
378	        client.query(api.writingActivity.getMyActivity, {
379	          from: recent.from!,
380	          to: recent.to,
381	        }),
382	        loadBreakdown("feature"),
383	        loadBreakdown("provider_model"),
384	        loadBreakdown("folio"),
385	        client.query(api.usage.listMyRecent, {
386	          paginationOpts: { numItems: 100, cursor: null },
387	        }),
388	        listPendingEvents(accountId, requested),
389	        usageLedger.listWritingActivity({
390	          from: requested.from ?? recent.from!,
391	          to: requested.to,
392	          limit: 2_000,
393	        }),
394	        folioMetadata(),
395	      ]);
396	      const boundedRecent = recentPage as unknown as {
397	        page: UsageEvent[];
398	        isDone: boolean;
399	      };
400	      if (cancelled) return;
401	      const summary = combineDeskUsage({
402	        range: requested,
403	        now: queriedAt,
404	        remoteOverall: remoteOverall as ServerUsageMetrics,
405	        remoteDaily: remoteDaily as ServerDailyUsage[],
406	        remoteBreakdowns: {
407	          feature: feature.rows,
408	          provider_model: providerModel.rows,
409	          folio: folio.rows,
410	        },
411	        remoteWriting: remoteWriting as ServerWritingActivity,
412	        recentServerEvents: boundedRecent.page,
413	        pendingEvents: pending.events,
414	        localActivities,
415	        folios: localFolios.metadata,
416	      });
417	      store.summary = summary;
418	      store.writingDays = summary.writingHeatmap.filter(
419	        (day) => day.count > 0,
420	      ).length;
421	      store.synchronized = coverage as SynchronizedCoverage;
422	      store.combinedPartial = combinedDataIsPartial([
423	        feature.truncated,
424	        providerModel.truncated,
425	        folio.truncated,
426	        !boundedRecent.isDone,
427	        pending.truncated,
428	        localActivities.length === 2_000,
429	        (remoteWriting as ServerWritingActivity).detailsTruncated,
430	      ]);
431	      store.remoteState = "ready";
432	    } catch {
433	      if (!cancelled)
434	        store.remoteState = navigator.onLine ? "error" : "offline";
435	    }
436	  });
437	
438	  // eslint-disable-next-line qwik/no-use-visible-task
439	  useVisibleTask$(({ track }) => {
440	    const loading = track(() => auth.value.loading);
441	    const signedIn = track(
442	      () => auth.value.provider === "convex" && Boolean(auth.value.user),
443	    );
444	    const range = track(() => preset.value);
445	    if (loading || deskViewCaptured.value) return;
446	    deskViewCaptured.value = true;
447	    void captureProductEvent("desk_viewed", {
448	      signed_in: signedIn,
449	      range,
450	    });
451	  });
452	
453	  const selectRange = $((range: UsageRangePreset) => {
454	    preset.value = range;
455	    history.replaceState(history.state, "", `/desk/?range=${range}`);
456	    void captureProductEvent("usage_range_changed", { range });
457	  });
458	
459	  const sourceState = !store.loaded
460	    ? "loading"
461	    : store.detailsTruncated ||
462	        store.combinedPartial ||
463	        store.remoteState === "error"
464	      ? "partial"
465	      : store.remoteState === "offline"
466	        ? "offline"
467	        : store.remoteState === "ready"
468	          ? "combined"
469	          : "local";
470	  // Subscribe the route render so nested billing views receive each transition.
471	  const hostedBilling = {
472	    state: hostedState.value,
473	    summary: hostedSummary.value,
474	  };
475	
476	  return (
477	    <main class="min-h-screen bg-[var(--color-paper)] px-4 py-8 text-[var(--color-ink)] sm:px-8">
478	      <div class="mx-auto max-w-6xl">
479	        <nav
480	          aria-label="Desk navigation"
481	          class="mb-5 flex items-center justify-between border-b border-dotted border-[var(--color-ink-muted)] pb-3 text-xs"
482	        >
483	          <Link href="/editor/" class="hover:text-[var(--color-vermilion)]">
484	            ← Writing room
485	          </Link>
486	          <span class="flex gap-4">
487	            <Link href="/account/" class="hover:text-[var(--color-vermilion)]">
488	              Account
489	            </Link>
490	            <Link href="/settings/" class="hover:text-[var(--color-vermilion)]">
491	              Preferences
492	            </Link>
493	          </span>
494	        </nav>
495	        <DeskSummary
496	          displayName={
497	            auth.value.user
498	              ? accountDisplayName(auth.value.user)
499	              : "Writer on this device"
500	          }
501	          signedIn={auth.value.provider === "convex"}
502	          rangeLabel={RANGE_LABELS[preset.value]}
503	          writingDays={store.writingDays}
504	          folioCount={store.folioCount}
505	          metrics={store.summary.overall}
506	          hostedState={hostedBilling.state}
507	          hostedSummary={hostedBilling.summary}
508	          sourceState={sourceState}
509	          combined={store.remoteState === "ready"}
510	          writingDaysLabel={
511	            preset.value === "all" ? "Days writing (recent 90)" : undefined
512	          }
513	          synchronized={store.synchronized}
514	        />
515	        <nav
516	          class="flex flex-wrap items-center gap-2 border-b border-dotted border-[var(--color-ink-muted)] py-4"
517	          aria-label="Usage range"
518	        >
519	          <span class="mr-2 text-xs font-semibold tracking-[0.1em] uppercase text-[var(--color-ink-muted)]">
520	            Range
521	          </span>
522	          {(["7d", "30d", "90d", "all"] as UsageRangePreset[]).map((range) => (
523	            <button
524	              key={range}
525	              type="button"
526	              aria-pressed={preset.value === range}
527	              class={{
528	                "btn-paper": true,
529	                "bg-[var(--color-ink)] text-[var(--color-paper)]":
530	                  preset.value === range,
531	              }}
532	              onClick$={() => selectRange(range)}
533	            >
534	              {range === "all" ? "All" : range.slice(0, -1)}
535	            </button>
536	          ))}
537	        </nav>
538	        {!store.loaded ? (
539	          <div class="py-20" role="status">
540	            <p class="dept-label">Reading the ledger</p>
541	            <div class="mt-4 h-px w-full animate-pulse bg-[var(--color-ink-muted)]" />
542	          </div>
543	        ) : (
544	          <>
545	            <WritingActivity
546	              days={store.summary.writingHeatmap}
547	              daily={store.summary.daily}
548	              folioTitles={store.titles}
549	              truncated={store.detailsTruncated || store.combinedPartial}
550	              windowLabel={
551	                preset.value === "all"
552	                  ? "Lifetime totals and breakdowns; daily writing and AI activity below cover the recent 90 UTC days."
553	                  : undefined
554	              }
555	            />
556	            <UsageCost
557	              summary={store.summary}
558	              totalsOnly={preset.value === "all"}
559	              hostedState={hostedBilling.state}
560	              hostedSummary={hostedBilling.summary}
561	              hostedRunway={hostedRunway.value}
562	              onRefreshHosted$={$(() => {
563	                hostedRevision.value += 1;
564	              })}
565	            />
566	            <WriterPatterns
567	              patterns={store.summary.patterns}
568	              folioTitles={store.titles}
569	            />
570	            <RecentWork
571	              entries={store.summary.recentWork}
572	              folioTitles={store.titles}
573	            />
574	            <p class="border-t-2 border-[var(--color-ink)] py-7 text-sm text-[var(--color-ink-muted)]">
575	              Export, sync across devices, or delete this history from{" "}
576	              <Link href="/account/#data" class="underline">
577	                Account → Your data
578	              </Link>
579	              .
580	            </p>
581	          </>
582	        )}
583	      </div>
584	    </main>
585	  );
586	});
587	
588	export const head: DocumentHead = {
589	  title: "My Desk · Twyne",
590	  meta: [
591	    {
592	      name: "description",
593	      content:
594	        "Review your writing activity, content-free AI usage, and costs.",
595	    },
596	  ],
597	};
