1	import { component$ } from "@qwik.dev/core";
2	
3	export interface ChartTableColumn {
4	  key: string;
5	  label: string;
6	}
7	
8	export interface ChartTableRow {
9	  key: string;
10	  cells: Record<string, string | number>;
11	}
12	
13	export const ChartTable = component$<{
14	  caption: string;
15	  columns: ChartTableColumn[];
16	  rows: ChartTableRow[];
17	  open?: boolean;
18	}>((props) => {
19	  return (
20	    <details
21	      class="mt-4 border-t border-dotted border-[var(--color-ink-muted)] pt-3"
22	      open={props.open}
23	    >
24	      <summary class="cursor-pointer text-xs font-semibold tracking-[0.12em] uppercase text-[var(--color-ink-muted)] focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-[var(--color-cobalt)]">
25	        View data table
26	      </summary>
27	      <div class="mt-3 overflow-x-auto">
28	        <table class="w-full border-collapse text-left text-sm">
29	          <caption class="sr-only">{props.caption}</caption>
30	          <thead>
31	            <tr class="border-y border-[var(--color-ink)]">
32	              {props.columns.map((column) => (
33	                <th
34	                  key={column.key}
35	                  scope="col"
36	                  class="px-2 py-2 text-xs tracking-[0.08em] uppercase"
37	                >
38	                  {column.label}
39	                </th>
40	              ))}
41	            </tr>
42	          </thead>
43	          <tbody>
44	            {props.rows.map((row) => (
45	              <tr
46	                key={row.key}
47	                class="border-b border-dotted border-[var(--color-ink-muted)]"
48	              >
49	                {props.columns.map((column, index) =>
50	                  index === 0 ? (
51	                    <th
52	                      key={column.key}
53	                      scope="row"
54	                      class="px-2 py-2 font-medium"
55	                    >
56	                      {row.cells[column.key]}
