101	async function listPendingEvents(
102	  accountId: string,
103	  range: UsageRange,
104	): Promise<EventPage> {
105	  const events: UsageEvent[] = [];
106	  let cursor: string | undefined;
107	  let pages = 0;
108	  do {
109	    const page = await usageLedger.listPendingUsageEvents({
110	      accountId,
111	      cursor,
112	      limit: 100,
113	    });
114	    events.push(
115	      ...page.events.filter(
116	        (event) =>
117	          event.occurredAt < range.to &&
118	          (range.from === null || event.occurredAt >= range.from),
119	      ),
120	    );
121	    cursor = page.cursor;
122	    pages += 1;
123	  } while (cursor && pages < MAX_LOCAL_PAGES);
124	  return { events, truncated: Boolean(cursor) };
125	}
