1	import { $, component$, useSignal, useVisibleTask$ } from "@qwik.dev/core";
2	import {
3	  useAuth,
4	  hasAuthenticatedConvexIdentity,
5	} from "../../utils/auth-context";
6	import { useConvexClient } from "../../utils/convex-context";
7	import {
8	  deskAcknowledgeRef,
9	  deskEnabledRef,
10	  deskPrepareRef,
