105	      hasAuthenticatedConvexIdentity(auth.value) ? auth.value.user?.id : null,
106	    );
107	    const client = track(() => convex.value);
108	    state.value = null;
109	    if (!identity || !client) return;
110	    cleanup(
111	      client.onUpdate(
112	        deskStatusRef,
113	        {},
114	        (value) => {
