154	        <input
155	          type="checkbox"
156	          checked={state.value?.enabled ?? false}
157	          disabled={
158	            !state.value ||
159	            busy.value ||
160	            (!state.value.enabled && !state.value.linkedDid)
161	          }
162	          onChange$={(event) =>
163	            toggle((event.target as HTMLInputElement).checked)
164	          }
165	        />
166	      </label>
167	      <p class="mt-2 text-xs leading-relaxed text-[var(--color-ink-light)]">
168	        Let other apps read your Twyne profile and the statistics selected above
169	        from your own public data server. Draft titles, text, and private
170	        activity details stay private. Public records can be copied by other
171	        apps.
172	      </p>
173	      <p class="mt-2 text-xs" role="status">
174	        {!state.value
175	          ? "Loading desk publishing…"
176	          : state.value.pending
177	            ? state.value.enabled
178	              ? "Publication or update pending. Keep Twyne open with your PDS connected."
179	              : "Removal pending. The previous public snapshot may remain until your PDS reconnects."
180	            : state.value.enabled
181	              ? auth.value.atproto?.did === state.value.did
182	                ? "Public desk synchronized. It refreshes while Twyne is open."
183	                : "Desk publishing is on. Reconnect your PDS to refresh the public snapshot."
184	              : "Desk publication is off. A private marker replaces any previously published details."}
185	      </p>
186	      {!state.value?.linkedDid && (
187	        <p class="mt-2 text-xs">
188	          Sign in with Not Organic to verify the PDS for this account.
189	        </p>
190	      )}
191	      {state.value?.did && (
192	        <div class="mt-3 flex flex-wrap gap-4 text-xs">
193	          <button type="button" class="underline" onClick$={connect}>
194	            Connect or renew PDS permission
195	          </button>
196	          {state.value.pending && (
197	            <button
198	              type="button"
199	              class="underline"
200	              onClick$={() =>
