1	import { component$, useVisibleTask$ } from "@qwik.dev/core";
2	import type { ConvexClient } from "convex/browser";
3	import { api } from "../../../convex/_generated/api";
4	import { useAuth } from "../../utils/auth-context";
5	import { useConvexClient } from "../../utils/convex-context";
6	import {
7	  syncLocalUsageHistory,
8	  type UsageBatchUploader,
9	  type UsageSyncResult,
10	} from "../../utils/usage-sync";
11	
12	export const USAGE_SYNC_REQUEST_EVENT = "twyne:usage-sync-requested";
13	export const USAGE_SYNC_STATE_EVENT = "twyne:usage-sync-state";
14	
15	export function createConvexUsageUploader(
16	  client: Pick<ConvexClient, "mutation">,
17	): UsageBatchUploader {
18	  return {
19	    async upload({ events }) {
20	      await client.mutation(api.usage.syncClientEvents, {
21	        events: [...events],
22	      });
23	      // The mutation is atomic and treats an existing event key as success, so
24	      // every offered row is safe to mark as present after it resolves.
25	      return {
26	        acknowledgedEventKeys: events.map((event) => event.eventKey),
27	      };
28	    },
29	  };
30	}
31	
32	function announceUsageSync(result: UsageSyncResult): void {
33	  window.dispatchEvent(
34	    new CustomEvent<UsageSyncResult>(USAGE_SYNC_STATE_EVENT, {
35	      detail: result,
36	    }),
37	  );
38	}
39	
40	/**
41	 * Consent-aware background uploader for the separate usage ledger. It never
42	 * enables synchronization, chooses an account, or joins the folio snapshot
43	 * loop; those decisions remain explicit Desk controls.
44	 */
45	export const UsageSyncController = component$(() => {
46	  const auth = useAuth();
47	  const clientSignal = useConvexClient();
48	
49	  // eslint-disable-next-line qwik/no-use-visible-task
50	  useVisibleTask$(
51	    ({ cleanup, track }) => {
52	      const client = track(() => clientSignal.value);
53	      const provider = track(() => auth.value.provider);
54	      const accountId = track(() => auth.value.user?.analyticsId);
55	      if (!client || provider !== "convex" || !accountId) return;
56	
57	      let disposed = false;
58	      let running = false;
59	      const synchronize = async () => {
60	        if (disposed || running || !navigator.onLine) return;
61	        running = true;
62	        try {
63	          const result = await syncLocalUsageHistory({
64	            accountId,
65	            uploader: createConvexUsageUploader(client),
66	          });
67	          if (!disposed) announceUsageSync(result);
68	        } catch {
69	          // Usage telemetry is an enhancement and must never interrupt writing.
70	          if (!disposed) {
71	            announceUsageSync({
72	              status: "partial",
73	              uploaded: 0,
74	              batches: 0,
75	            });
76	          }
77	        } finally {
78	          running = false;
79	        }
80	      };
81	
82	      void synchronize();
83	      window.addEventListener("online", synchronize);
84	      window.addEventListener(USAGE_SYNC_REQUEST_EVENT, synchronize);
85	      cleanup(() => {
86	        disposed = true;
87	        window.removeEventListener("online", synchronize);
88	        window.removeEventListener(USAGE_SYNC_REQUEST_EVENT, synchronize);
89	      });
90	    },
91	    { strategy: "document-ready" },
92	  );
93	
94	  return null;
95	});
