     1	/**
     2	 * GitHub-style "days writing" contribution heatmap. Renders the last ~371
     3	 * days as week-columns of 7 day-squares, colored by activity count.
     4	 */
     5	
     6	import { component$, type QRL } from "@qwik.dev/core";
     7	
     8	export interface ActivityDay {
     9	  day: string; // "YYYY-MM-DD"
    10	  count: number;
    11	}
    12	
    13	const DAY_MS = 24 * 60 * 60 * 1000;
    14	const WEEKS = 53;
    15	
    16	export function levelFor(count: number): 0 | 1 | 2 | 3 | 4 {
    17	  if (count <= 0) return 0;
    18	  if (count === 1) return 1;
    19	  if (count <= 3) return 2;
    20	  if (count <= 6) return 3;
    21	  return 4;
    22	}
    23	
    24	/**
    25	 * A ramp from the paper rule up to full accent. Mixed rather than fixed so
    26	 * the heatmap re-inks itself with the active theme instead of staying a strip
    27	 * of warm orange on a cool or dark page.
    28	 */
    29	const LEVEL_COLORS = [
    30	  "var(--color-paper-3)",
    31	  "color-mix(in srgb, var(--color-vermilion) 22%, var(--color-paper-3))",
    32	  "color-mix(in srgb, var(--color-vermilion) 48%, var(--color-paper-3))",
    33	  "color-mix(in srgb, var(--color-vermilion) 74%, var(--color-paper-3))",
    34	  "var(--color-vermilion)",
    35	];
    36	
    37	export interface HeatmapCell {
    38	  day: string;
    39	  count: number;
    40	}
    41	
    42	export function buildHeatmapWeeks(
    43	  days: readonly ActivityDay[],
    44	  now = Date.now(),
    45	): HeatmapCell[][] {
    46	  const byDay = new Map(days.map((day) => [day.day, day.count]));
    47	  const today = new Date(now);
    48	  today.setUTCHours(0, 0, 0, 0);
    49	  const totalDays = WEEKS * 7;
    50	  const endDow = today.getUTCDay();
    51	  const start = new Date(
    52	    today.getTime() - (totalDays - 1 - (6 - endDow)) * DAY_MS,
    53	  );
    54	  const weeks: HeatmapCell[][] = [];
    55	  let cursor = new Date(start);
    56	  for (let week = 0; week < WEEKS; week += 1) {
    57	    const column: HeatmapCell[] = [];
    58	    for (let day = 0; day < 7; day += 1) {
    59	      const key = cursor.toISOString().slice(0, 10);
    60	      column.push({
    61	        day: key,
    62	        count: cursor.getTime() > today.getTime() ? -1 : (byDay.get(key) ?? 0),
    63	      });
    64	      cursor = new Date(cursor.getTime() + DAY_MS);
    65	    }
    66	    weeks.push(column);
    67	  }
    68	  return weeks;
    69	}
    70	
    71	export interface WritingHeatmapProps {
    72	  days: ActivityDay[];
    73	  now?: number;
    74	  selectedDay?: string;
    75	  partialDays?: string[];
    76	  onSelectDay$?: QRL<(day: string) => void>;
    77	}
    78	
    79	export const WritingHeatmap = component$<WritingHeatmapProps>((props) => {
    80	  const weeks = buildHeatmapWeeks(props.days, props.now);
    81	  const partialDays = new Set(props.partialDays ?? []);
    82	  const totalContributions = props.days.reduce(
    83	    (sum, day) => sum + day.count,
    84	    0,
    85	  );
    86	
    87	  return (
    88	    <div>
    89	      <div class="flex gap-[3px] overflow-x-auto pb-1">
    90	        {weeks.map((col, wi) => (
    91	          <div key={wi} class="flex flex-col gap-[3px]">
    92	            {col.map((cell, di) => (
    93	              <button
    94	                key={di}
    95	                type="button"
    96	                disabled={cell.count < 0 || !props.onSelectDay$}
    97	                aria-label={
    98	                  cell.count >= 0
    99	                    ? `${cell.day}: ${cell.count} ${cell.count === 1 ? "entry" : "entries"}${partialDays.has(cell.day) ? ", partial detail" : ""}`
   100	                    : undefined
   101	                }
   102	                aria-pressed={props.selectedDay === cell.day}
   103	                onClick$={() => props.onSelectDay$?.(cell.day)}
   104	                class="h-[10px] w-[10px] rounded-[1px] p-0 enabled:cursor-pointer enabled:focus-visible:outline-2 enabled:focus-visible:outline-offset-2 enabled:focus-visible:outline-[var(--color-cobalt)]"
   105	                style={{
   106	                  background:
   107	                    cell.count < 0
   108	                      ? "transparent"
   109	                      : LEVEL_COLORS[levelFor(cell.count)],
   110	                  boxShadow:
   111	                    props.selectedDay === cell.day
   112	                      ? "0 0 0 1px var(--color-ink)"
   113	                      : partialDays.has(cell.day)
   114	                        ? "inset 0 0 0 1px var(--color-ink-muted)"
   115	                        : undefined,
   116	                }}
   117	              />
   118	            ))}
   119	          </div>
   120	        ))}
   121	      </div>
   122	      <div
   123	        class="mt-2 flex items-center gap-2 text-[10px] tracking-[0.1em] uppercase text-[var(--color-ink-muted)]"
   124	        style="font-family: var(--font-typewriter);"
   125	      >
   126	        <span>{totalContributions} entries in the last year</span>
   127	        <span class="ml-auto flex items-center gap-1 normal-case tracking-normal">
   128	          Less
   129	          {LEVEL_COLORS.map((c) => (
   130	            <span
   131	              key={c}
   132	              class="h-[10px] w-[10px] rounded-[2px]"
   133	              style={{ background: c }}
   134	            />
   135	          ))}
   136	          More
   137	        </span>
   138	      </div>
   139	    </div>
   140	  );
   141	});

